Old evening rule: leave living room light on and curtain mostly open.

MEMBER: override.json
{
  "output": "override-summary.md",
  "precedence": "override beats old_rules",
  "changes": [
    {
      "room": "living room",
      "device": "light",
      "state": "off"
    },
    {
      "room": "living room",
      "device": "curtain",
      "open_pct": 20
    },
    {
      "room": "kitchen",
      "device": "air purifier",
      "level": "high"
    }
  ]
}

